        /// - POST <a href="https://developers.newline53.com/reference/post_returns">Create a new Return: POST /returns</a>
        /// - GET <a href="https://developers.newline53.com/reference/get_returns-uid">Get a single Return: GET /returns/{uid}</a>
        /// <br/>
        /// The returns endpoint allows for the retrieval and creation of return transactions within the system.<br/>
        /// <br/>
        /// <a href="https://newline-enterprise-group.readme.io/reference/get_returns">GET List Returns</a>- Use this endpoint to retrieve a list of all return transactions. You can filter the results based on various parameters such as status or date.<br/>
        /// <br/>
        /// <a href="https://newline-enterprise-group.readme.io/reference/post_returns">POST Create a New Return</a>- This endpoint is used to Create a new return transaction. Return can only be created for eligible transactions that have already been completed.<br/>
        /// <br/>
        /// <a href="https://newline-enterprise-group.readme.io/reference/get_returns-uid">GET a Single Return</a>- Use this endpoint to retrieve details about a specific return transaction.
        /// </summary>
        public IReturns Returns { get; }

        public ICombinedTransfers CombinedTransfers { get; }
    }

    /// <summary>
    /// Newline Platform API: <br/>
    /// Welcome! In this section of our docs experience, you'll be able to go through common payment scenarios that both you and your end customers may encounter as you start to offer financial products through your own technology stack. These guides will also help to highlight and expand on concepts discussed in our API references, like <a href="https://developers.newline53.com/reference/synthetic-accounts">Synthetic Accounts</a>, <a href="https://developers.newline53.com/reference/transfers">Transfers</a>, <a href="https://developers.newline53.com/reference/transactions">Transactions&amp;nbsp;</a>  and <a href="https://developers.newline53.com/reference/customers">Customers</a>.<br/>
    /// <br/>
    /// Our guides are broken out by supported use cases. If you find there isn't a specific use case that fits your business, reach out to our <a href="https://newline53.com/contact-us.html">Sales &amp;amp; Partnership team</a> and they'll be able to help determine how we can support your business and provide any other questions or feedback.<br/>
    /// <br/>
    /// Lastly, when you're ready to build, check out our <a href="https://developers.newline53.com/docs/overview">Onboarding Overview</a> and <a href="https://developers.newline53.com/docs/sandbox-walkthrough">Sandbox Walkthrough</a> guides.<br/>
    /// <br/>
    /// ## About our API<br/>
    /// <br/>
    /// The Newline API is organized around REST. With a few exceptions, our API has standard resource-oriented URLs, accepts form-encoded OR JSON-encoded request bodies, returns JSON-encoded responses, and uses standard HTTP response codes, authentication, and verbs.<br/>
    /// <br/>
    /// ## FAQs<br/>
    /// <br/>
    /// Want to quickly review some common questions about Newline and our financial experiences, check out our <a href="https://developers.newline53.com/docs/faqs">FAQs</a> guide.<br/>
    /// <br/>
    /// # Overview<br/>
    /// <br/>
    /// ## Newline Onboarding 101<br/>
    /// <br/>
    /// Onboarding to any SaaS product can be a daunting task, and at Newline we seek to make this experience as smooth as possible. Part of that is getting you, our Client, familiar with the process by which we establish key resources like your Program, Products, Customers, Custodial Accounts, and Synthetic Accounts.<br/>
    /// <br/>
    /// The following guide details, in short order, the Program and resources that Newline will configure for you and how each of these components affect your ability to use our API Reference.<br/>
    /// <br/>
    /// &lt;img src="https://files.readme.io/955347d-image.png"&gt;<br/>
    /// <br/>
    /// The above visualization shows the Program and resources Newline will provide and maintain for Clients going through onboarding and implementation, but we'll enumerate the details for each resource above.<br/>
    /// <br/>
    /// &gt; **Note**<br/>
    /// &gt; In the above visualization, the lighter color items are preset and created by Newline for any Client implementation. Synthetic Accounts is a special case where general Synthetic Accounts are preset and Clients will be responsible for creating their own external Synthetic Accounts and VRNs..<br/>
    /// <br/>
    /// - **Program** - the Program dictates the origination terms to which the Client and Newline mutually agree. This could include payment limitations like amounts, frequency, and the need for pre-funding (ex. ACH). Your Program will be created and configured by Newline.<br/>
    /// <br/>
    /// - **Products** - these are distinct Product offerings supported by Newline. For instance, this can include payment rails like ACH, Wire, and Instant Payments that are configured as available synthetic_account_types. Newline creates and configures a Program's Products.<br/>
    /// <br/>
    ///     - Products can be applied across multiple Customers, and Customers can be attached to multiple Products. Essentially there is a many-to-many relationship between these resources, which make them, in some cases, parallel.<br/>
    /// <br/>
    ///     - A Product can support multiple payment rails.<br/>
    /// <br/>
    /// - **Customer Type** - Customers are provided a Customer Type at creation. For instance, Primary Customers are considered full account owners and have complete authority to take any actions associated with their accounts and associated resources. You can also limit certain Customer Types to have access to only certain Products. Permitted Customer Types are configured by Newline.<br/>
    /// <br/>
    /// - **Pool** - Container for one or more Synthetic Accounts, with Assets owned by one or more Customers. Pools allow for shared assets and flexibility in ownership and transfer of assets. Newline will create Pools.<br/>
    /// <br/>
    /// - **Customer** - This is the entity that owns the Account and Funds stored at Newline. This entity also is deemed the Originator when it comes to any payment creation. Clients can also be Customers in the event they meet those criteria. Customers are created by Newline or by the Client depending on the use case.<br/>
    /// <br/>
    /// - **Custodial Account** - This is the Account that exists in our Synthetic Core and represents the reciprocal Account on Fifth Third's ledger. These are the accounts you can access via Fifth Third Direct. Custodial Accounts will be created by Newline.<br/>
    /// <br/>
    /// - **Synthetic Account** - How Newline represents the assets held by your Customers. These are the accounts that Customers view and interact with on your application. Synthetic Accounts are also used to manage external accounts that your Customers will likely use within your application. Synthetic Accounts of the general category will be created by Newline or by the Client depending on your use case. Clients will create external Synthetic Accounts like wire_external, ach_external, and instant_payment_external.<br/>
    /// <br/>
    /// - **Virtual Reference Number** - Virtual Reference Numbers (or VRNs) are virtualized account numbers. They are aliases to a synthetic account and can form a many-to-one relationship with their parent synthetic account.<br/>
    /// <br/>
    /// # Postman Collection<br/>
    /// <br/>
    /// How to set up Postman, add our Newline collection, and use it to test Newline platform APIs.<br/>
    /// <br/>
    /// ## Installing Postman<br/>
    /// <br/>
    /// Postman is available on a variety of platforms. Visit <a href="https://www.postman.com/downloads/">Postman</a> to see if your platform is supported.  <br/>
    /// To install Postman:<br/>
    /// <br/>
    /// 1. Go to <a href="https://www.postman.com/downloads/">Postman downloads</a>.<br/>
    /// <br/>
    /// &lt;img src="https://files.readme.io/fd1743f-Postman_Dowload_snip.jpg"&gt;<br/>
    /// <br/>
    /// 1. Download the required version.<br/>
    /// <br/>
    /// 2. After your download is complete, run the downloaded file to install Postman.<br/>
    /// <br/>
    /// ## Import the Newline Collection<br/>
    /// <br/>
    /// To import our collection, click on the following <a href="https://www.postman.com/newline53">▶ Newline Collection</a> button, and you will be redirected to our Newline Postman workspace, where you can download our collection.<br/>
    /// <br/>
    /// For further information, see the <a href="https://learning.postman.com/docs/getting-started/importing-and-exporting-data/">Postman documentation on importing data</a>.<br/>
    /// <br/>
    /// ## Configure Your Postman Environment<br/>
    /// <br/>
    /// 1. Create a Sandbox Environment.<br/>
    /// <br/>
    /// 2. Set Sandbox variables.<br/>
    /// <br/>
    /// 3. Save the environment.<br/>
    /// <br/>
    /// 4. Ensure the new environment is selected.<br/>
    /// <br/>
    /// **Set API Keys**  <br/>
    /// You will need to set your HMAC Key and Program UID as environment variables. You can set the variables in the headers in the environment tab within the Postman Collection.<br/>
    /// <br/>
    /// # Terminology<br/>
    /// <br/>
    /// The terms, which represent API resource objects in Newline, below are referenced in our API documentation and endpoint definitions.  <br/>
    /// Some important notes while reading through this list:<br/>
    /// <br/>
    /// Resource Objects often interact with one another, so please be sure to review our endpoints to see which serve as required inputs or are collected as outputs.<br/>
    /// <br/>
    /// Certain objects, like Transfers, are described differently in the payments industry depending on the Transaction Type. For instance, ach transactions are often referred to as entries rather than payments, as they can represent both credits (i.e., ODFI pushes) and debits (i.e., ODFI pulls).  <br/>
    /// While Resource Objects are distinct, they, in some cases, can represent the same entity.<br/>
    /// <br/>
    /// - Ex. 1 - Clients can also be Customers if they manage and own the financial products in question.<br/>
    /// <br/>
    /// - Ex. 2 - Transfers produce Transactions, but the produced Transactions (in aggregate) represent the original money movement.<br/>
    /// <br/>
    /// | Term | Definition |<br/>
    /// | --- | --- |<br/>
    /// | Customer | The end user of your application and the owner of assets in your Program. For example, when initiating a payment, this entity would be considered the **originator**. |<br/>
    /// | Client | The application or product owning organization that is affording end users (i.e., Customers) the ability to access the financial products.&lt;br&gt;&lt;br&gt;&lt;br&gt;**Note**&lt;br&gt;Clients can also be Customers in the event they own and have management over the financial products or the funds involved. |<br/>
    /// | Transmitter | Transmitters are the parties who have _requested_ the Transfer in question. When the Transmitter and Customer are the same party, Newline pulls origination information from the created Customer record. When the Transmitter and Customer are not the same party, it's the Client's responsibility to provide that information when making a Transfer.  &lt;br&gt;  &lt;br&gt;Transmitters are only required for the `wire` and `instant_payment` types (see the `wire_transmitter` and `instant_payment_transmitter` objects in the <a href="https://developers.newline53.com/reference/post_transfers">Initiate a Transfer</a> reference). Client's should also take note of the `initiator_type` field, which dictates from where Transmitter information is pulled. For more context on Transmitters, refer to the <a href="https://newline-enterprise-group.readme.io/docs/transfer#payment-rail-regulation">Payment Rail Regulation</a> section below. |<br/>
    /// | Partner | Any infrastructure partner integrated within the Newline Platform. |<br/>
    /// | Program | The Program is custom tailored to your offering and purpose built to enable financial products on your application. The Program defines what Synthetic and Custodial Account types, Customer Types, and Transactions Types are available for your Customers to utilize. The Program configuration is defined between the Client and Newline based on your (i.e., the Client's) use case. |<br/>
    /// | Product | Products represents the financial products available to your Customers. The Product object contains the account, compliance, and customer profile responses necessary for your Customers to gain access. |<br/>
    /// | Customer Product | The Customer Product is created when the Customer is added to a Product and respective Program. This often includes Newline automatically creating any needed financial products for the Customers' use. For instance, a Synthetic Account to represent the origination account at Fifth Third. |<br/>
    /// | Service Offering | The financial product offered by the Newline platform. These can be (but are not limited to) checking, savings, brokerage, or retirement accounts. |<br/>
    /// | Pool | Container for one or more Synthetic Accounts, with Assets owned by one or more Customers. Pools allow for shared assets and flexibility in ownership and transfer of assets. |<br/>
    /// | Custodial Accounts | This resource within Newline represents the assets held by your Customers, with direct alignment to accounts opened at Fifth Third. Custodial Accounts have the following relationships: one-to-one with Customers, and one-to-Many with Synthetic Accounts. |<br/>
    /// | Synthetic Accounts | How Newline represents the assets held by your Customers. These are the accounts that Customers view and interact with on your application. Synthetic Accounts are also used to manage external accounts (i.e., Counterparties) that your Customers will likely use within your application. |<br/>
    /// | Virtual Reference Number (VRN) | Virtual Reference Numbers (or VRNs) are virtualized account numbers. They are aliases to a Synthetic Account, and can form a many-to-one relationship with their parent Synthetic Account. |<br/>
    /// | Transfer | The movement of assets from one Synthetic Account to another Synthetic Account. Most of asset movement initiated by your application will result in a Transfer. A successful Transfer will result in at least one Transaction. |<br/>
    /// | Transaction | Transactions are created based on how you instruct Newline to move assets (a Transfer) or how assets are moved or spent outside of your application (For example, ACH, Wire, and Instant Payments Transfers). The Transaction contains the amount, origin, and destination of assets. Newline categorizes Transactions into types to assist in their classification and representation. |<br/>
    /// | Transaction Events | The steps taken to complete the Transaction. These can be used to view the progress of an in-flight Transaction or see the history of a completed Transaction. |
    /// </summary>
    public class NewlineSDK : INewlineSDK
    {
        /// <summary>
        /// The main SDK Configuration.
        /// </summary>
        public SDKConfig SDKConfiguration { get; private set; }
        /// <summary>
        /// The Auth sub-SDK.
        /// </summary>
        public IAuth Auth { get; private set; }
        /// <summary>
        /// The Customers sub-SDK.
        /// </summary>
        public ICustomers Customers { get; private set; }
        /// <summary>
        /// The Pools sub-SDK.
        /// </summary>
        public IPools Pools { get; private set; }
        /// <summary>
        /// The Products sub-SDK.
        /// </summary>
        public IProducts Products { get; private set; }
        /// <summary>
        /// The CustomerProducts sub-SDK.
        /// </summary>
        public ICustomerProducts CustomerProducts { get; private set; }
        /// <summary>
        /// The CustodialAccounts sub-SDK.
        /// </summary>
        public ICustodialAccounts CustodialAccounts { get; private set; }
        /// <summary>
        /// The SyntheticAccounts sub-SDK.
        /// </summary>
        public ISyntheticAccounts SyntheticAccounts { get; private set; }
        /// <summary>
        /// The Transfers sub-SDK.
        /// </summary>
        public ITransfers Transfers { get; private set; }
        /// <summary>
        /// The Transactions sub-SDK.
        /// </summary>
        public ITransactions Transactions { get; private set; }
        /// <summary>
        /// The VirtualReferenceNumbers sub-SDK.
        /// </summary>
        public IVirtualReferenceNumbers VirtualReferenceNumbers { get; private set; }
        /// <summary>
        /// The Returns sub-SDK.
        /// </summary>
        public IReturns Returns { get; private set; }
        /// <summary>
        /// The CombinedTransfers sub-SDK.
        /// </summary>
        public ICombinedTransfers CombinedTransfers { get; private set; }

        /// <summary>
        /// Initializes a new instance of the SDK based on a <see cref="SDKConfig"/> configuration object.
        /// </summary>
        /// <param name="config">The SDK configuration object.</param>
        public NewlineSDK(SDKConfig config)
        {
            SDKConfiguration = config;
            InitHooks();

            Auth = new Auth(SDKConfiguration);

            Customers = new Customers(SDKConfiguration);

            Pools = new Pools(SDKConfiguration);

            Products = new Products(SDKConfiguration);

            CustomerProducts = new CustomerProducts(SDKConfiguration);

            CustodialAccounts = new CustodialAccounts(SDKConfiguration);

            SyntheticAccounts = new SyntheticAccounts(SDKConfiguration);

            Transfers = new Transfers(SDKConfiguration);

            Transactions = new Transactions(SDKConfiguration);

            VirtualReferenceNumbers = new VirtualReferenceNumbers(SDKConfiguration);

            Returns = new Returns(SDKConfiguration);

            CombinedTransfers = new CombinedTransfers(SDKConfiguration);
        }

        /// <summary>
        /// Initializes a new instance of the SDK with optional configuration parameters.
        /// </summary>
        /// <param name="security">The security configuration to use for API requests. If provided, this will be used as a static security configuration.</param>
        /// <param name="securitySource">A function that returns the security configuration dynamically. This takes precedence over the static security parameter if both are provided.</param>
        /// <param name="server">The server to use from the predefined server list.</param>
        /// <param name="serverUrl">A custom server URL to use instead of the predefined server list. If provided with urlParams, the URL will be templated with the provided parameters.</param>
        /// <param name="urlParams">A dictionary of parameters to use for templating the serverUrl. Only used when serverUrl is provided.</param>
        /// <param name="client">A custom HTTP client implementation to use for making API requests. If not provided, the default NewlineSDKHttpClient will be used.</param>
        /// <param name="retryConfig">Configuration for retry behavior when API requests fail. Defines retry strategies, backoff policies, and maximum retry attempts.</param>
        /// <exception cref="ArgumentException">None of <paramref name="security"/> and <paramref name="securitySource"/> were provided.</exception>
        public NewlineSDK(
            Newline53.Sdk.Models.Components.Security? security = null,
            Func<Newline53.Sdk.Models.Components.Security>? securitySource = null,
            SDKConfig.Server? server = null,
            string? serverUrl = null,
            Dictionary<string, string>? urlParams = null,
            INewlineSDKHttpClient? client = null,
            RetryConfig? retryConfig = null
        )
        {

            if (serverUrl != null)
            {
                if (urlParams != null)
                {
                    serverUrl = Utilities.TemplateUrl(serverUrl, urlParams);
                }
            }
            Func<Newline53.Sdk.Models.Components.Security>? _securitySource = null;

            if (securitySource != null)
            {
                _securitySource = securitySource;
            }
            else if (security != null)
            {
                _securitySource = () => security;
            }
            else
            {
                throw new ArgumentException("security and securitySource cannot both be null");
            }

            SDKConfiguration = new SDKConfig(client) {
                ServerName = server,
                ServerUrl = serverUrl == null ? "" : serverUrl,
                SecuritySource = _securitySource,
                RetryConfig = retryConfig
            };

            InitHooks();

            Auth = new Auth(SDKConfiguration);

            Customers = new Customers(SDKConfiguration);

            Pools = new Pools(SDKConfiguration);

            Products = new Products(SDKConfiguration);

            CustomerProducts = new CustomerProducts(SDKConfiguration);

            CustodialAccounts = new CustodialAccounts(SDKConfiguration);

            SyntheticAccounts = new SyntheticAccounts(SDKConfiguration);

            Transfers = new Transfers(SDKConfiguration);

            Transactions = new Transactions(SDKConfiguration);

            VirtualReferenceNumbers = new VirtualReferenceNumbers(SDKConfiguration);

            Returns = new Returns(SDKConfiguration);

            CombinedTransfers = new CombinedTransfers(SDKConfiguration);
        }

        private void InitHooks()
        {
            SDKConfiguration = SDKConfiguration.Hooks.SDKInit(SDKConfiguration);
        }

        /// <summary>
        /// Builder class for constructing an instance of the SDK.
        /// </summary>
        public class SDKBuilder
        {
            private SDKConfig _sdkConfig = new SDKConfig(client: new NewlineSDKHttpClient());

            public SDKBuilder()
            {
            }

            /// <summary>
            /// Overrides the default server by name.
            /// </summary>
            public SDKBuilder WithServer(SDKConfig.Server server)
            {
                _sdkConfig.ServerName = server;
                return this;
            }

            /// <summary>
            /// Overrides the default server URL for the SDK.
            /// </summary>
            public SDKBuilder WithServerUrl(string serverUrl, Dictionary<string, string>? serverVariables = null)
            {
                if (serverVariables != null)
                {
                    serverUrl = Utilities.TemplateUrl(serverUrl, serverVariables);
                }
                _sdkConfig.ServerUrl = serverUrl;
                return this;
            }

            /// <summary>
            /// Sets the securitySource security parameter for the SDK.
            /// </summary>
            public SDKBuilder WithSecuritySource(Func<Newline53.Sdk.Models.Components.Security> securitySource)
            {
                _sdkConfig.SecuritySource = securitySource;
                return this;
            }

            /// <summary>
            /// Sets the security security parameter for the SDK.
            /// </summary>
            public SDKBuilder WithSecurity(Newline53.Sdk.Models.Components.Security security)
            {
                _sdkConfig.SecuritySource = () => security;
                return this;
            }

            /// <summary>
            /// Sets a custom HTTP client to be used by the SDK.
            /// </summary>
            public SDKBuilder WithClient(INewlineSDKHttpClient client)
            {
                _sdkConfig.Client = client;
                return this;
            }

            /// <summary>
            /// Sets the retry configuration for the SDK.
            /// </summary>
            public SDKBuilder WithRetryConfig(RetryConfig retryConfig)
            {
                _sdkConfig.RetryConfig = retryConfig;
                return this;
            }

            /// <summary>
            /// Builds and returns the SDK instance.
            /// </summary>
            public NewlineSDK Build()
            {
                if (_sdkConfig.SecuritySource == null)
                {
                    throw new ArgumentException("securitySource cannot be null. One of `Security` or `securitySource` needs to be defined.");
                }
                return new NewlineSDK(_sdkConfig);
            }
        }

        public static SDKBuilder Builder() => new SDKBuilder();
    }
}